<?php require_once __DIR__ . '/includes/auth.php'; $user=require_role(['tenant_admin','manager','employee']); $pdo=db(); check_tenant_active($pdo); $tid=require_tenant(); $base=''; $active='reports'; $pageTitle='Reports';
function rep(PDO $pdo,string $sql,array $a){$s=$pdo->prepare($sql);$s->execute($a);return $s->fetchAll();}
$perf=rep($pdo,'SELECT p.name,p.status,p.progress,p.budget,COUNT(t.id) tasks,SUM(t.status="done") done FROM projects p LEFT JOIN tasks t ON t.project_id=p.id AND t.tenant_id=? WHERE p.tenant_id=? GROUP BY p.id ORDER BY p.id DESC',[$tid,$tid]);
$completion=rep($pdo,'SELECT status,COUNT(*) total FROM tasks WHERE tenant_id=? GROUP BY status',[$tid]);
$timeByProject=rep($pdo,'SELECT p.name,COALESCE(SUM(l.minutes),0) minutes FROM projects p LEFT JOIN time_logs l ON l.project_id=p.id AND l.tenant_id=? WHERE p.tenant_id=? GROUP BY p.id ORDER BY minutes DESC',[$tid,$tid]);
$overdue=rep($pdo,'SELECT t.title,t.due_date,t.priority,u.name assignee,p.name project_name FROM tasks t LEFT JOIN users u ON u.id=t.assigned_to LEFT JOIN projects p ON p.id=t.project_id WHERE t.tenant_id=? AND t.status!="done" AND t.due_date<CURDATE() ORDER BY t.due_date',[$tid]);
$byUser=rep($pdo,'SELECT u.name,COUNT(t.id) assigned,SUM(t.status="done") done,COALESCE(SUM(l.minutes),0) minutes FROM users u LEFT JOIN tasks t ON t.assigned_to=u.id AND t.tenant_id=? LEFT JOIN time_logs l ON l.user_id=u.id AND l.tenant_id=? WHERE u.tenant_id=? GROUP BY u.id',[$tid,$tid,$tid]);
if(isset($_GET['export'])) { $rows=[]; foreach($perf as $r) $rows[]=['project'=>$r['name'],'status'=>$r['status'],'progress_%'=>$r['progress'],'budget'=>$r['budget'],'tasks'=>$r['tasks'],'done'=>$r['done']]; foreach($overdue as $r) $rows[]=['project'=>'OVERDUE: '.$r['title'],'status'=>$r['priority'],'progress_%'=>'','budget'=>'','tasks'=>'','done'=>'due '.$r['due_date']]; export_csv($rows,'project-report.csv'); }
include __DIR__ . '/includes/header.php'; ?>
<div class="mb-3"><a class="btn btn-outline-success" href="?export=1">Export CSV (project performance + overdue)</a></div>
<div class="row g-3"><div class="col-lg-6"><div class="card p-3"><h6>Project performance</h6><table class="table"><tr><th>Project</th><th>Status</th><th>Progress</th><th>Tasks done</th></tr><?php foreach($perf as $r): ?><tr><td><?= e($r['name']) ?></td><td><?= e($r['status']) ?></td><td><?= (int)$r['progress'] ?>%</td><td><?= (int)$r['done'] ?>/<?= (int)$r['tasks'] ?></td></tr><?php endforeach; ?></table></div></div>
<div class="col-lg-6"><div class="card p-3"><h6>Task completion by status</h6><canvas id="compChart" height="140"></canvas><table class="table mt-2"><?php foreach($completion as $r): ?><tr><td><?= e($r['status']) ?></td><td><?= (int)$r['total'] ?></td></tr><?php endforeach; ?></table></div></div>
<div class="col-lg-6"><div class="card p-3"><h6>Time by project</h6><table class="table"><?php foreach($timeByProject as $r): ?><tr><td><?= e($r['name']) ?></td><td><?= round($r['minutes']/60,2) ?> hours</td></tr><?php endforeach; ?></table></div>
<div class="card p-3 mt-3"><h6>Team productivity</h6><table class="table"><tr><th>Member</th><th>Assigned</th><th>Done</th><th>Logged</th></tr><?php foreach($byUser as $r): ?><tr><td><?= e($r['name']) ?></td><td><?= (int)$r['assigned'] ?></td><td><?= (int)$r['done'] ?></td><td><?= round($r['minutes']/60,2) ?> h</td></tr><?php endforeach; ?></table></div></div>
<div class="col-lg-6"><div class="card p-3 border-danger"><h6 class="text-danger">Overdue tasks (<?= count($overdue) ?>)</h6><table class="table"><tr><th>Task</th><th>Project</th><th>Assignee</th><th>Due</th></tr><?php foreach($overdue as $r): ?><tr><td><?= e($r['title']) ?></td><td><?= e($r['project_name']??'') ?></td><td><?= e($r['assignee']??'') ?></td><td class="text-danger"><?= e($r['due_date']) ?></td></tr><?php endforeach; if(!$overdue) echo '<tr><td colspan="4" class="text-muted">Nothing overdue. Nice.</td></tr>'; ?></table></div></div></div>
<?php $extraJs='<script>makeChart("compChart","doughnut",'.json_encode(array_column($completion,'status')).','.json_encode(array_map('intval',array_column($completion,'total'))).',"Tasks");</script>'; include __DIR__ . '/includes/footer.php'; ?>
